"use strict";

const ARTICLES = {"socotra":{"reference":"EXP-2026","category":"NATURALEZA","categoryKey":"naturaleza","title":"Socotra: la isla que parece un planeta equivocado","deck":"Un archipiélago del océano Índico donde una proporción extraordinaria de especies es endémica.","date":"2026-08-31","dateLabel":"31 AGO 2026","readTime":"06 MIN","rarity":5,"location":"Socotra, Yemen","coordinates":"12°29′N / 53°54′E","image":"https://commons.wikimedia.org/wiki/Special:Redirect/file/Dragonblood_tree_in_Socotra_1.jpg","imageAlt":"Árbol de sangre de dragón en Socotra con las montañas Hajhir al fondo","imageCredit":"Alex38 / Wikimedia Commons · CC BY-SA 4.0","body":["Socotra no necesita una leyenda para resultar extraña. Su aislamiento geográfico ayudó a conservar una flora y fauna excepcionalmente diferenciadas, hasta el punto de que UNESCO señala que el 37% de sus especies vegetales no se encuentran de forma natural en ningún otro lugar del mundo.","Uno de sus símbolos es Dracaena cinnabari, el árbol de sangre de dragón. Su copa en forma de paraguas y su savia rojiza han convertido a la especie en una de las imágenes más reconocibles del archipiélago.","La explicación de su aspecto no es extraterrestre ni sobrenatural. Es evolución, aislamiento, clima y una historia biogeográfica muy larga. Precisamente por eso Socotra funciona tan bien para este archivo: parece inventada, pero la anomalía está en la naturaleza real."],"sources":[{"label":"UNESCO World Heritage Centre","url":"https://whc.unesco.org/en/list/1263"},{"label":"Wikimedia Commons · fotografía","url":"https://commons.wikimedia.org/wiki/File:Dragonblood_tree_in_Socotra_1.jpg"}]},"hessdalen":{"reference":"EXP-1184","category":"CIENCIA_RARA","categoryKey":"ciencia","title":"Las luces de Hessdalen","deck":"Un fenómeno luminoso investigado durante décadas mediante cámaras, radar, magnetómetros y otros instrumentos.","date":"2026-08-29","dateLabel":"29 AGO 2026","readTime":"07 MIN","rarity":4,"location":"Hessdalen, Noruega","coordinates":"62°47′N / 11°10′E","image":"https://commons.wikimedia.org/wiki/Special:Redirect/file/Hessdalen_lights.png","imageAlt":"Registro de larga exposición de una luz de Hessdalen","imageCredit":"SuperWikiaBros / Wikimedia Commons · CC BY-SA 4.0","body":["Las luces de Hessdalen son uno de esos casos donde lo interesante empieza cuando se elimina la exageración. El fenómeno ha sido observado en el valle de Hessdalen, Noruega, y Project Hessdalen mantiene un archivo de observaciones e instrumentación.","El proyecto fue establecido en 1983. Según su propio archivo, una campaña de campo de 1984 registró 53 fenómenos con cámaras, radar, magnetómetros y otros instrumentos. Desde 1998, su sistema conocido como Blue Box ha continuado registrando actividad.","Eso no demuestra un origen extraterrestre. El propio proyecto señala que su objetivo es recopilar datos medibles y ponerlos a disposición para análisis. En otras palabras: el expediente documenta un fenómeno observado, no una explicación definitiva."],"sources":[{"label":"Project Hessdalen · archivo y metodología","url":"https://www.hessdalen.org/about"},{"label":"Project Hessdalen · archivo visual","url":"https://www.hessdalen.org/pictures-and-videos"},{"label":"Wikimedia Commons · fotografía","url":"https://commons.wikimedia.org/wiki/File:Hessdalen_lights.png"}]},"mary-celeste":{"reference":"EXP-0821","category":"HISTORIA_OCULTA","categoryKey":"historia","title":"El Mary Celeste: el barco que apareció sin su tripulación","deck":"En diciembre de 1872, otro buque encontró al Mary Celeste a la deriva en el Atlántico. La tripulación había desaparecido.","date":"2026-08-26","dateLabel":"26 AGO 2026","readTime":"08 MIN","rarity":4,"location":"Atlántico, al este de las Azores","coordinates":"38°20′N / 17°15′W","image":"https://commons.wikimedia.org/wiki/Special:Redirect/file/Mary_Celeste_as_Amazon_in_1861.jpg","imageAlt":"Pintura del bergantín Amazon, posteriormente rebautizado como Mary Celeste","imageCredit":"Wikimedia Commons · dominio público","body":["El 5 de diciembre de 1872, la tripulación del Dei Gratia avistó un barco a la deriva a unas 400 millas al este de las Azores. Era el Mary Celeste, que había salido de Nueva York con rumbo a Génova.","Cuando subieron a bordo no encontraron a ninguna de las diez personas que habían viajado en él. El barco seguía con provisiones y gran parte de su carga, mientras que el bote salvavidas había desaparecido. Una de las bombas estaba desmontada y había agua acumulada en la sentina.","La investigación realizada en Gibraltar no encontró pruebas de juego sucio. Desde entonces se han propuesto numerosas explicaciones, pero el destino de la tripulación sigue sin resolverse de forma concluyente. La historia real es suficientemente extraña sin necesidad de añadir monstruos marinos o conspiraciones."],"sources":[{"label":"Smithsonian Magazine · investigación histórica","url":"https://www.smithsonianmag.com/history/abandoned-ship-the-mary-celeste-174488104/"},{"label":"Wikimedia Commons · imagen histórica","url":"https://commons.wikimedia.org/wiki/File:Mary_Celeste_as_Amazon_in_1861.jpg"}]},"wow-signal":{"reference":"EXP-1977","category":"CIENCIA_RARA","categoryKey":"ciencia","title":"La señal Wow!","deck":"Una señal de radio de banda estrecha detectada en 1977. Duró 72 segundos y nunca volvió a aparecer de la misma manera.","date":"2026-08-23","dateLabel":"23 AGO 2026","readTime":"07 MIN","rarity":5,"location":"Dirección celeste asociada con Sagitario","coordinates":"≈ RA 19h22m / Dec −27°","image":"https://commons.wikimedia.org/wiki/Special:Redirect/file/Wow_signal.jpg","imageAlt":"Copia del registro impreso de la señal Wow! de 1977","imageCredit":"Big Ear Radio Observatory / Wikimedia Commons · dominio público","body":["El 15 de agosto de 1977, el radiotelescopio Big Ear de la Universidad Estatal de Ohio detectó una señal de radio de banda estrecha durante un barrido rutinario del cielo. La señal duró aproximadamente 72 segundos.","El registro apareció como una secuencia de intensidad conocida como 6EQUJ5. El astrónomo Jerry Ehman la encontró al revisar la impresión de datos y escribió “Wow!”, una anotación que terminó convirtiéndose en el nombre del evento.","El SETI Institute resume el punto clave: la señal nunca volvió a observarse. Por eso sigue siendo un caso fascinante, pero no constituye una prueba de una transmisión extraterrestre. La anomalía está documentada; su origen continúa sin resolución definitiva."],"sources":[{"label":"SETI Institute · The Wow! Signal","url":"https://www.seti.org/research/seti-101/the-wow-signal/"},{"label":"Big Ear · archivo histórico","url":"https://www.bigear.org/"}]},"blood-falls":{"reference":"EXP-2110","category":"NATURALEZA","categoryKey":"naturaleza","title":"Blood Falls: la corriente roja bajo el hielo","deck":"En la Antártida, una salmuera rica en hierro emerge desde el glaciar Taylor y adquiere un color rojo intenso al oxidarse.","date":"2026-08-19","dateLabel":"19 AGO 2026","readTime":"06 MIN","rarity":5,"location":"Glaciar Taylor, Antártida","coordinates":"77°43′S / 162°16′E","image":"https://commons.wikimedia.org/wiki/Special:Redirect/file/Blood_Falls_2010_01.jpg","imageAlt":"Blood Falls en el frente del glaciar Taylor, Antártida","imageCredit":"Peter West / National Science Foundation · dominio público","body":["Blood Falls es una descarga rojiza en el frente del glaciar Taylor, en los valles secos de McMurdo. El aspecto parece sangre, pero el color tiene una explicación química.","NASA describe el fenómeno como una salmuera rica en hierro que se filtra desde debajo del glaciar. Cuando el hierro entra en contacto con el oxígeno, se producen los tonos rojizos que hacen tan llamativa la escena.","La historia es todavía más interesante debajo del hielo: investigaciones han documentado un sistema de salmuera subglacial y comunidades microbianas asociadas. No es una cascada de sangre, sino una ventana a un ecosistema extremo que permanece aislado bajo un glaciar."],"sources":[{"label":"NASA Earth Observatory · Blood Falls","url":"https://science.nasa.gov/earth/earth-observatory/blood-falls-antarcticas-dry-valleys-35535/"},{"label":"National Science Foundation · Science on the Ice","url":"https://nsf-gov-resources.nsf.gov/files/NSF-Science-on-the-Ice-fifth-edition.pdf"}]},"voynich":{"reference":"EXP-1666","category":"HISTORIA_OCULTA","categoryKey":"historia","title":"El Manuscrito Voynich: el libro que sigue sin descifrarse","deck":"Un manuscrito ilustrado de finales del siglo XV o comienzos del XVI, escrito en un sistema que permanece sin interpretar de forma aceptada.","date":"2026-08-15","dateLabel":"15 AGO 2026","readTime":"08 MIN","rarity":5,"location":"Beinecke Library, Yale University","coordinates":"MS 408","image":"https://commons.wikimedia.org/wiki/Special:Redirect/file/Voynich_Manuscript_(100).jpg","imageAlt":"Página ilustrada del Manuscrito Voynich","imageCredit":"Wikimedia Commons · consultar licencia del archivo","body":["La Beinecke Library de Yale identifica el manuscrito como Beinecke MS 408 y sitúa su producción en Europa Central a finales del siglo XV o durante el siglo XVI. Su autor es desconocido y el sistema de escritura tampoco ha sido identificado de manera concluyente.","El libro reúne secciones con dibujos de plantas, imágenes astronómicas y astrológicas, diagramas cosmológicos, escenas relacionadas con baños, ilustraciones farmacéuticas y páginas de texto sin ilustraciones.","Los intentos criptográficos por descifrarlo no han producido una interpretación aceptada. Yale también señala que las pruebas científicas son consistentes con materiales de manuscritos del siglo XV. La pieza existe, está catalogada y puede estudiarse mediante las imágenes digitales de la biblioteca; lo que permanece abierto es qué significa exactamente su texto."],"sources":[{"label":"Yale Beinecke Library · Manuscrito Voynich","url":"https://beinecke.library.yale.edu/beinecke/collections/beinecke-cipher-voynich-manuscript"},{"label":"Wikimedia Commons · página del manuscrito","url":"https://commons.wikimedia.org/wiki/File:Voynich_Manuscript_(100).jpg"}]}};

const state = { filter: "all", layout: "grid", lastFocus: null };
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const modal = $("#modal");

function updateClock() {
  const el = $("#currentDate");
  if (!el) return;
  const now = new Date();
  el.textContent = new Intl.DateTimeFormat("es-MX", {
    weekday: "short", day: "2-digit", month: "short", year: "numeric"
  }).format(now).replace(/\./g, "").toUpperCase();
  el.dateTime = now.toISOString();
}

function applyTheme(theme) {
  document.documentElement.dataset.theme = theme;
  localStorage.setItem("ca-theme", theme);
  const button = $("#themeToggle");
  if (button) {
    const light = theme === "light";
    button.setAttribute("aria-pressed", String(light));
    button.setAttribute("aria-label", light ? "Activar modo oscuro" : "Activar modo claro");
  }
}

function initTheme() {
  const saved = localStorage.getItem("ca-theme");
  if (saved === "light" || saved === "dark") applyTheme(saved);
  else applyTheme(matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark");
}

function setLayout(layout) {
  state.layout = layout;
  $$(".layout-btn").forEach(button => {
    const active = button.dataset.layout === layout;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", String(active));
  });
  $("#grid").hidden = layout !== "grid";
  $("#list").hidden = layout !== "list";
  window.refreshArchiveAnimations?.();
}

function setFilter(filter) {
  state.filter = filter;
  $$(".filter").forEach(button => button.classList.toggle("is-active", button.dataset.filter === filter));
  $$(".card, .list-row").forEach(item => {
    item.classList.toggle("is-hidden", filter !== "all" && item.dataset.category !== filter);
  });
  window.refreshArchiveAnimations?.();
}

function fillModal(id) {
  const a = ARTICLES[id];
  if (!a) return false;

  $("#modalRef").textContent = a.reference;
  $("#modalCategory").textContent = "#" + a.category;
  $("#modalLocation").textContent = a.location;
  $("#modalCoordinates").textContent = a.coordinates;
  $("#modalRarity").textContent = a.rarity + "/5";
  $("#modalRead").textContent = a.readTime;
  $("#modalCredit").textContent = a.imageCredit || "";
  $("#modalTag").textContent = "#" + a.category;
  $("#modalTitle").textContent = a.title;
  $("#modalDeck").textContent = a.deck;

  const image = $("#modalImage");
  image.src = a.image;
  image.alt = a.imageAlt;

  const body = $("#modalBody");
  body.replaceChildren(...a.body.map(text => {
    const p = document.createElement("p");
    p.textContent = text;
    return p;
  }));

  const sources = $("#modalSources");
  sources.replaceChildren(...a.sources.map(source => {
    const link = document.createElement("a");
    link.className = "source-link";
    link.href = source.url;
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    const label = document.createElement("span");
    label.textContent = source.label;
    const arrow = document.createElement("span");
    arrow.textContent = "↗";
    link.append(label, arrow);
    return link;
  }));

  return true;
}

function openModal(id, writeHistory = true) {
  if (!fillModal(id) || !modal) return;
  state.lastFocus = document.activeElement;
  modal.classList.add("is-open");
  modal.setAttribute("aria-hidden", "false");
  document.body.classList.add("modal-open");

  if (writeHistory) {
    history.pushState({ article: id }, "", `${location.pathname}?exp=${encodeURIComponent(id)}`);
  }
  $("#modalClose")?.focus();
  window.animateModal?.(true);
}

function finishClose(writeHistory = true) {
  if (writeHistory && location.search) {
    history.pushState({}, "", location.pathname + location.hash);
  }
  modal.classList.remove("is-open");
  modal.setAttribute("aria-hidden", "true");
  document.body.classList.remove("modal-open");
  state.lastFocus?.focus?.();
}

window.finishClose = finishClose;

function closeModal(writeHistory = true) {
  if (!modal?.classList.contains("is-open")) return;
  if (window.animateModal) window.animateModal(false, writeHistory);
  else finishClose(writeHistory);
}

function initDeepLink() {
  const id = new URLSearchParams(location.search).get("exp");
  if (id && ARTICLES[id]) openModal(id, false);
}

function bind() {
  $("#themeToggle")?.addEventListener("click", () => {
    applyTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark");
  });

  $$(".layout-btn").forEach(button => button.addEventListener("click", () => setLayout(button.dataset.layout)));
  $$(".filter").forEach(button => button.addEventListener("click", () => setFilter(button.dataset.filter)));

  $$("[data-open-article]").forEach(button => {
    button.addEventListener("click", event => {
      event.stopPropagation();
      openModal(button.dataset.openArticle);
    });
  });

  $$(".hero-card, .card").forEach(card => {
    card.addEventListener("click", event => {
      if (!event.target.closest("button, a")) openModal(card.dataset.articleId);
    });
    card.addEventListener("keydown", event => {
      if ((event.key === "Enter" || event.key === " ") && !event.target.closest("button")) {
        event.preventDefault();
        openModal(card.dataset.articleId);
      }
    });
  });

  $$("[data-close]").forEach(el => el.addEventListener("click", () => closeModal()));
  $("#modalClose")?.addEventListener("click", () => closeModal());

  document.addEventListener("keydown", event => {
    if (event.key === "Escape" && modal.classList.contains("is-open")) closeModal();
  });

  window.addEventListener("popstate", () => {
    const id = new URLSearchParams(location.search).get("exp");
    if (id && ARTICLES[id]) openModal(id, false);
    else if (modal.classList.contains("is-open")) finishClose(false);
  });

  $$("img").forEach(img => img.addEventListener("error", () => {
    img.dataset.failed = "true";
    img.removeAttribute("src");
  }, { once: true }));
}

document.addEventListener("DOMContentLoaded", () => {
  initTheme();
  updateClock();
  setInterval(updateClock, 60000);
  bind();
  setLayout("grid");
  setFilter("all");
  initDeepLink();
});
